from iaia.models import ModernizationAction
class ModernizationPlanner:
    def plan(self, findings, redesign):
        actions=[]
        if findings: actions.append(ModernizationAction(phase='1. Immediate risk reduction', title='Triage static security indicators', priority='urgent', evidence='; '.join(f.title for f in findings), reason='Reduce potentially unsafe behavior before structural changes.', steps=['Confirm each indicator with owners','Remove or constrain risky behavior','Rotate any confirmed exposed credentials'], dependencies=[], validation=['Security-focused tests','Review static findings again'], rollback='Use version control to revert each reviewed change.', benefits=['Reduced immediate risk'], uncertainty='Static indicators may be false positives.'))
        if redesign: actions.append(ModernizationAction(phase='2. Dependency and design improvements', title='Define boundaries and interfaces', priority='high', evidence='; '.join(x.title for x in redesign), reason='Make responsibilities and dependency direction reviewable.', steps=['Choose an owner for each boundary','Add contracts and adapters','Migrate one caller at a time'], dependencies=['Triage static security indicators'] if findings else [], validation=['Unit and contract tests','Compare dependency graph'], rollback='Retain adapters until migration is validated.', benefits=['Lower coupling and safer changes'], uncertainty='Target boundaries are recommendations requiring review.'))
        actions.append(ModernizationAction(phase='4. Validation and controlled migration', title='Run staged regression review', priority='medium', evidence='Analysis coverage and graph outputs', reason='Verify that proposed changes preserve behavior.', steps=['Baseline tests','Migrate a small slice','Review findings and blast radius','Approve next slice'], dependencies=['Define boundaries and interfaces'] if redesign else [], validation=['Automated tests and peer review'], rollback='Revert the slice and keep the prior interface available.', benefits=['Controlled migration'], uncertainty='No timeline or performance claim is made.'))
        return actions
